ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
    "status": "400",
    "code": "BILLING_DISPUTE:INVALID_PARAMS",
    "message": "CONNECTION_NUMBER, BILLING_ACCOUNT and (CUSTOMER_ID_TYPE - CUSTOMER_ID) combination cant be empty at the same time.",
    "messageServer": error.description,
    "cause": [
        {
            "origin": "customer-papi-services-v2",
            "message": "CONNECTION_NUMBER, BILLING_ACCOUNT and (CUSTOMER_ID_TYPE - CUSTOMER_ID) combination cant be empty at the same time.",
        }
    ]
}

%dw 2.0
var zsmartResponse = payload.result.result
output application/json  skipNullOn="everywhere"
---
{
  "codeResponse": "200",
  "messageResponse": "OK",
  "accounts": [
    {
      "accountNumber": vars.billingAccount,
      "disputes": zsmartResponse.disputeExDtoList map (dispute, index) -> {
        "disputeID": dispute.disputeID,
        "amount": dispute.amount,
        "remarks": dispute.remarks,
        "createdDate": dispute.createdDate,
        "status": dispute.status,
        "disputeItems": dispute.disputeItemExDtoList map (disputeItem, indez) -> {
          "glID": disputeItem.glID,
          "refInvoiceNumber": disputeItem.refInvoiceNumber,
          "amount": disputeItem.amount,
          "glTypeID": disputeItem.glTypeID,
          "glTypeName": disputeItem.glTypeName
        }
      }
    }
  ]
}

%dw 2.0
output application/json
---
{
	basePath: p("mongo-db-sapi.base-path"),
	host: p("mongo-db-sapi.host"),
	port: p("mongo-db-sapi.port"),
	method: "POST",
	path: p('mongo-db-sapi.resources.dynamicQuery.base-path'),
	body: {
		"query": {
			"aggregate": "MDM_CUENTA_FACTURACION",
			"pipeline": [{
				"\$match": {
					"Tipo_Documento": vars.billingParams.'CUSTOMER_ID_TYPE',
					"Numero_Identificacion": vars.billingParams.'CUSTOMER_ID'
				}
			}],
			"cursor": {
			}
		}
	},
	headers: vars.billingHeaders default {
	},
	queryParameters: {
	},
	uriParameters: {
	}
}
